const csv=($input.first().json.data)||'';
function parseCSV(t){const R=[];let row=[],f='',q=false;for(let i=0;i<t.length;i++){const c=t[i];
 if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++;}else q=false;}else f+=c;}
 else{if(c==='"')q=true;else if(c===','){row.push(f);f='';}else if(c==='\n'){row.push(f);R.push(row);row=[];f='';}else if(c==='\r'){}else f+=c;}}
 if(f.length||row.length){row.push(f);R.push(row);}return R;}
const raw=parseCSV(csv).filter(r=>r.length>1);
const H=(raw.shift()||[]).map(h=>h.trim());
const idx={};H.forEach((h,i)=>idx[h]=i);
const g=(r,k)=>{const i=idx[k];return i==null?'':String(r[i]||'').trim();};
const num=(r,k)=>parseFloat(g(r,k))||0;
const rows=raw.map(r=>({
 rank:parseInt(g(r,'rank'))||0,restaurant:g(r,'restaurant'),area:g(r,'area'),cuisine:g(r,'cuisine')||'Other',category:g(r,'category'),
